data.solution:
import numpy as np


def log_ratio(I1, I2, eps=1e-6):
    I1 = np.asarray(I1, dtype=np.float64)
    I2 = np.asarray(I2, dtype=np.float64)
    if I1.shape != I2.shape:
        raise ValueError(
            f'log_ratio: niezgodne ksztalty I1 {I1.shape} vs I2 {I2.shape}'
        )
    return np.log((I2 + eps) / (I1 + eps))
